/* GENERATED by tools/build-legal.py from docs/legal/*.md (and he/). Do not edit by hand.
 * The in-app Legal reader renders exactly these bodies; the standalone pages in legal/ are built from the same text. */
(function (root) { var Stick = root.Stick = root.Stick || {}; Stick.legalContent = {"order": ["privacy", "terms", "copyright", "young", "storage", "accessibility"], "docs": {"en": {"privacy": {"title": "Privacy Policy", "file": "privacy.html", "html": "<h1>Privacy Policy (DRAFT)</h1>\n<blockquote class=\"draftNote\"><p><strong>Draft for review. Not legal advice and not final.</strong> This text describes what <span class=\"bw\">Stick-It</span> actually does today. It has <strong>not</strong> been reviewed by a lawyer, and items marked <code><mark class=\"todo\">[OWNER INPUT REQUIRED: ...]</mark></code> or <code><mark class=\"todo\">[LEGAL REVIEW RECOMMENDED]</mark></code> still need the owner or a lawyer. It stays a draft until the contact e-mail is configured, every placeholder is resolved, the owner approves it and legal review has been completed or knowingly accepted.</p></blockquote>\n<p>Last updated: 2026-10-01 (draft version 2026-10-01-draft)</p>\n<h2>1. Who runs <span class=\"bw\">Stick-It</span></h2>\n<p><span class=\"bw\">Stick-It</span> is operated by <strong>Jonathan Zachevsky</strong>, an individual in <strong>Israel</strong>. No company has been formed. Public postal address: <mark class=\"todo\">[PUBLIC POSTAL ADDRESS NOT CONFIGURED]</mark>. Privacy contact: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>.</p>\n<h2>2. The short version</h2>\n<ul><li><strong>As a guest</strong> you can use <span class=\"bw\">Stick-It</span> without an account. Your boards stay in your browser on your device. We do not receive them.</li><li><strong>If you create an account</strong>, we store your account details and the boards, notes, pictures, voice memos and videos you put in it, so they follow you between devices.</li><li><strong>Share links</strong> show what you choose to share to anyone who has the link.</li><li>We currently run <strong>no advertising and no session recording</strong>, and we do not currently use product analytics. We do not sell personal data. Product analytics may be introduced later (see section 9); if so, this policy is updated first, and analytics will never read your notes, comments, searches or private media.</li><li><strong>Young people:</strong> children under 13 may use <span class=\"bw\">Stick-It</span> only as guests until verified parental consent exists. See section 14 and the <a href=\"young-people.html\">Young people and parents</a> page.</li></ul>\n<h2>3. Data we collect, and why</h2>\n<div class=\"tableWrap\"><table><thead><tr><th scope=\"col\">What</th><th scope=\"col\">Examples</th><th scope=\"col\">Why</th></tr></thead><tbody><tr><td><strong>Account sign-in details</strong> (Google, GitHub or an e-mail code)</td><td>E-mail address, name or username, profile picture address, the provider's identifier for you</td><td>To create and secure your account</td></tr><tr><td><strong>Age band</strong></td><td>Only the result of the age step: adult, teen or child, the time you confirmed it, and (for children) a parental-consent status. <strong>Your date of birth, and the month and year you type, are not sent to us and not stored.</strong></td><td>To apply the right protections for your age</td></tr><tr><td><strong>Document versions</strong></td><td>The version of the Terms and Privacy Policy you were shown</td><td>To record what you were told</td></tr><tr><td><strong>Profile</strong></td><td>Display name, optional username, optional short bio, profile picture, a fallback colour/emoji</td><td>To show who you are in the app and on links you share</td></tr><tr><td><strong>Preferences</strong></td><td>How you appear on shared links, handwriting font, default note colour, and whether you want product-update e-mails (<strong>off unless you turn it on, and not available under 18</strong>; we record when you changed it)</td><td>To apply your choices</td></tr><tr><td><strong>Your content</strong></td><td>Boards, notes (text, formatting, positions), pictures, voice memos, videos, board covers</td><td>To provide the service</td></tr><tr><td><strong>Collaboration data</strong></td><td>Boards you belong to and your role; invitations you create</td><td>To let people share boards</td></tr><tr><td><strong>Comments and review</strong></td><td>The text of comments you add to an object, who wrote them and when; a review state on an object (changes requested / ready for review) with an optional short reason</td><td>To let collaborators discuss an object. Visible to everyone on that board</td></tr><tr><td><strong>Presence</strong> (not stored)</td><td>While a shared board is open: your display name, and which object you are editing or moving</td><td>To show who is here and to stop two people editing one note at once. It lives only while the page is open and is not saved</td></tr><tr><td><strong>Cutouts</strong></td><td>The cutout picture you make from a photo (stored like any picture). <strong>Cutouts are made on your device: your photo is not sent to any service for this</strong></td><td>To show a photo as a sticker</td></tr><tr><td><strong>Share links</strong></td><td>A copy of what you shared, the name/picture/bio you chose to show, whether the link is active. The link's secret address is stored only as a one-way hash</td><td>To make links work and let you turn them off</td></tr><tr><td><strong>Reports</strong></td><td>Content or copyright reports you send us</td><td>To handle abuse and copyright complaints</td></tr><tr><td><strong>Technical and security data</strong></td><td>Standard request data (IP address, device/browser type, time) is processed by our hosting and database providers</td><td>To deliver and protect the service</td></tr></tbody></table></div>\n<p><span class=\"bw\">Stick-It</span> does not currently collect your phone number, postal address, payment details, contacts, precise location or date of birth.</p>\n<p><strong>Possible future features.</strong> <span class=\"bw\">Stick-It</span> may introduce optional features in the future that require additional information, such as payment information, a phone number, contacts or location. If that happens, this policy and any relevant in-product notice will be updated before those features collect that information. In outline, and only if such features are built:</p>\n<ul><li><strong>Phone number:</strong> possibly for one-time verification codes or account recovery. Optional communications would be sent only where the law allows and only if you specifically agree to them; giving a phone number would not by itself be agreement to marketing.</li><li><strong>Payment information:</strong> Premium may later use an external payment provider. We would aim for full card numbers to be handled by that provider rather than stored by <span class=\"bw\">Stick-It</span>. No payment provider is active today.</li><li><strong>Contacts:</strong> possibly to help you invite people to a board. We would ask for explicit permission, prefer contacts you select, and not silently upload a whole address book unless that were truly necessary.</li><li><strong>Location:</strong> possibly for optional features such as map pins or location-linked notes. Nothing in <span class=\"bw\">Stick-It</span> today needs your location, including for offline use.</li></ul>\n<h2>4. Whether you must give it</h2>\n<p>You do not need an account to use <span class=\"bw\">Stick-It</span> as a guest. Creating an account needs a Google or GitHub sign-in and the age step; without them we cannot offer an account. Everything else is optional.</p>\n<h2>5. Notice at collection</h2>\n<p>This policy is the notice at collection: who runs <span class=\"bw\">Stick-It</span> (section 1), what is collected and why (section 3), whether you must provide it (section 4) and who receives it (section 7). The sign-in screen links to it, and to the Terms, before you continue. You can also use <span class=\"bw\">Stick-It</span> as a guest without signing in. If you sign in with e-mail, we receive your address and Supabase sends you a one-time code; <span class=\"bw\">Stick-It</span> does not store the code or a password.</p>\n<h2>6. How we use it</h2>\n<p>To provide, secure and maintain <span class=\"bw\">Stick-It</span>; sync your boards; show your name, picture and bio on links <strong>only if you chose that</strong>; apply age-based protections; answer reports and legal requests; and keep the service reliable. We do not use your content to train AI models, we do not sell it, and we do not use it for advertising. <mark class=\"todo\">[OWNER INPUT REQUIRED: confirm this reflects intent]</mark></p>\n<p><strong>Access to your content.</strong> <span class=\"bw\">Stick-It</span> does not routinely inspect your private content. Your boards are stored in our cloud infrastructure, so limited access can happen where it is necessary to operate and secure the service, to provide support you have asked for, to look into content that is reported or reasonably suspected of breaking the law or the Terms, to enforce the Terms, or to meet a legal obligation. Routine browsing of private content is not part of how <span class=\"bw\">Stick-It</span> works.</p>\n<p><strong>Responsibility for content.</strong> You are responsible for making sure that what you create, upload or share complies with the law and with the Terms. Where a violation is reported or reasonably suspected, <span class=\"bw\">Stick-It</span> may investigate and may restrict or remove content or an account where that is appropriate. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED]</mark></p>\n<h2>7. Who receives it</h2>\n<ul><li><strong>Service providers</strong> that run <span class=\"bw\">Stick-It</span>: <strong>Supabase</strong> (database, sign-in, file storage, server functions) and <strong>GitHub</strong> (website hosting through GitHub Pages).</li><li><strong>Sign-in providers.</strong> If you use Google or GitHub, they learn that you use <span class=\"bw\">Stick-It</span>. If your picture comes from them, your browser loads it from their servers.</li><li><strong>Anyone with a link you create.</strong> A share link shows what you shared to anyone who has it, without an account.</li><li><strong>Other members of boards you share</strong> can see that board's content and your display name.</li><li><strong>Authorities,</strong> where we are legally required to, or to protect people's safety or rights. <mark class=\"todo\">[OWNER INPUT REQUIRED: legal-process policy]</mark></li></ul>\n<p>We do not sell personal data and do not share it for advertising.</p>\n<h2>8. Marketing e-mail</h2>\n<p>Product-update e-mail is <strong>off by default</strong>, only for adults who switch it on, and never sent to people under 18. Every message must carry a one-click unsubscribe link, the sender's identity and a valid contact. <strong>No marketing e-mail is sent today.</strong> It stays disabled until a public postal address and sender are configured. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED: Israeli Communications Law section 30A]</mark></p>\n<h2>9. Browser storage, cookies and analytics</h2>\n<p><span class=\"bw\">Stick-It</span> currently does not set its own browser cookies. Instead, it uses browser storage such as local storage and IndexedDB for guest boards, preferences, cached board data and session-related information. These technologies serve similar persistence purposes but are technically different from cookies. This storage is needed for the app to work. Clearing browser data removes it; signing out removes the signed-in copy. See the <a href=\"storage.html\">Storage notice</a>.</p>\n<p><strong>Third-party content.</strong> If you choose to show a supported video link as an embedded video, your browser contacts that video provider's servers to play it, and the provider may use cookies or similar technologies under its own policy. A link kept as a plain link contacts nothing until you open it.</p>\n<p><strong>Possible future changes.</strong> Product analytics (for example counts of accounts, boards, object types, feature use, errors and performance, never the content of your notes, comments, searches or private media), payment processing or other embedded providers may use cookies or similar technologies in future. If that happens, this policy and the Storage notice will be updated at the same time.</p>\n<h2>10. International processing</h2>\n<p>Our providers may process data outside Israel. <mark class=\"todo\">[OWNER INPUT REQUIRED: the region of the Supabase project and where GitHub Pages serves from]</mark>. Israeli rules on transfers of data abroad apply. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED: transfer basis]</mark></p>\n<h2>11. How long we keep it</h2>\n<div class=\"tableWrap\"><table><thead><tr><th scope=\"col\">Data</th><th scope=\"col\">Kept</th></tr></thead><tbody><tr><td>Account, profile, preferences, boards, files</td><td>Until you delete them or your account</td></tr><tr><td>Notes you delete</td><td>Marked deleted so Undo works, then permanently removed by a daily clean-up job once they have been deleted for more than 30 days</td></tr><tr><td>Files no longer used by anything</td><td>Removed by the same daily job after a 14-day grace period</td></tr><tr><td>Abandoned sign-ups (an account that never finished the age step and owns nothing)</td><td>Removed by the same daily job after 7 days</td></tr><tr><td>Share links</td><td>Until you turn them off or delete your account</td></tr><tr><td>Age result on your device</td><td>Kept in your browser until you clear it; never contains a birth date</td></tr><tr><td>Comments and review states</td><td>Until they are deleted, or the object, board or account is deleted</td></tr><tr><td>Reports</td><td><mark class=\"todo\">[OWNER INPUT REQUIRED: how long reports are kept]</mark></td></tr><tr><td>Provider logs and backups</td><td>Controlled by Supabase and GitHub. <mark class=\"todo\">[OWNER INPUT REQUIRED: retention for the chosen plan]</mark></td></tr></tbody></table></div>\n<h2>12. Deleting your account and getting a copy</h2>\n<p><strong>In the app:</strong> Account settings, then Delete account (you type DELETE). This removes your profile and settings, the boards you own with everything on them, your uploaded files and picture, your share links (they stop working immediately, including snapshots), your invitations and memberships, then your sign-in account.</p>\n<p><strong>Not removed:</strong> notes you added to someone else's board (they stay, without your name), reports you sent us, data in provider logs or backups until they expire, and your Google or GitHub account and the permission you gave <span class=\"bw\">Stick-It</span> (revoke it with them). We do not claim instant erasure of backups.</p>\n<p><strong>Copy of your data:</strong> Account settings, Data &amp; privacy, Export my boards. It does not yet include voice-memo and video files or each link's secret address. For anything else write to <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>.</p>\n<h2>13. Your rights</h2>\n<p>Under Israeli privacy law you may have the right to see data we hold about you and to ask for it to be corrected or deleted. Write to <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>; we will answer as the law requires. You may complain to the Israeli Privacy Protection Authority. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED: exact rights and timelines after Amendment 13]</mark></p>\n<h2>14. Children and teens</h2>\n<p><span class=\"bw\">Stick-It</span> is a general-audience service. We do not market to anyone under 18.</p>\n<ul><li><strong>Adults (18+):</strong> full use.</li><li><strong>Teens (13-17):</strong> accounts allowed with conservative defaults: no marketing e-mail, links show no profile details by default, no public profile.</li><li><strong>Children (under 13):</strong> guest use on their own device only. A cloud account is not available until a parent or guardian has given verified consent. <strong>That mechanism does not exist yet.</strong> If a child's account exists (for example created by getting around the age step), we restrict cloud features and keep it pending; we do not delete it automatically.</li></ul>\n<p><strong>False age information.</strong> If we reasonably determine that an account used false age information to get around age protections, we may suspend or delete the account and its associated cloud data, subject to applicable law and any retention we are legally required to keep. Active account data may be deleted; provider logs and backups may persist for a time; <span class=\"bw\">Stick-It</span> does not keep deleted content merely for future use. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED: this must stay consistent with the Young people and parents page, which describes pending restricted accounts]</mark></p>\n<p>Parents and guardians: see <a href=\"young-people.html\">Young people and parents</a>. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED]</mark></p>\n<h2>15. Security</h2>\n<p>Boards and files are stored in a private database and private file storage behind per-user access rules; media is delivered with short-lived links. Share links work for anyone who has them. No system is perfectly secure and we cannot guarantee it. To report a security problem write to <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>. If a breach affects you we will tell you and, where the law requires, the authorities. See the internal breach plan in <code>docs/security/israel-data-breach-plan.md</code>.</p>\n<h2>16. Automated decisions</h2>\n<p>We do not make decisions about you by profiling or automated means that have legal or similarly significant effect.</p>\n<h2>17. Registration with the Privacy Protection Authority</h2>\n<p>Whether the database must be registered, and whether a data protection officer is required, depends on facts and thresholds that have not been confirmed. See <code>docs/legal/israel-compliance-audit.md</code>. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED]</mark></p>\n<h2>18. Third-party sites</h2>\n<p>Links to other websites are outside our control. Their privacy practices are their own.</p>\n<h2>19. Changes</h2>\n<p>We will post changes here with the date and tell account holders in the app about material changes.</p>\n<h2>20. Language</h2>\n<p>A Hebrew version of this policy is provided. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED: which version governs]</mark></p>\n<h2>21. Contact</h2>\n<p>Operator: Jonathan Zachevsky, Israel. Privacy: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>. Public postal address: <mark class=\"todo\">[PUBLIC POSTAL ADDRESS NOT CONFIGURED]</mark>.</p>"}, "terms": {"title": "Terms of Service", "file": "terms.html", "html": "<h1>Terms of Service (DRAFT)</h1>\n<blockquote class=\"draftNote\"><p><strong>Draft for review. Not legal advice and not final.</strong> This text describes how <span class=\"bw\">Stick-It</span> works today. It has <strong>not</strong> been reviewed by a lawyer. Items marked <code><mark class=\"todo\">[LEGAL REVIEW RECOMMENDED]</mark></code> or <code><mark class=\"todo\">[OWNER INPUT REQUIRED: ...]</mark></code> must be completed or checked before launch. This draft stays a draft until the contact e-mail is configured, every placeholder is resolved, the owner approves it and legal review has been completed or knowingly accepted.</p></blockquote>\n<p>Last updated: 2026-10-01 (draft version 2026-10-01-draft)</p>\n<h2>1. About <span class=\"bw\">Stick-It</span> and who runs it</h2>\n<p><span class=\"bw\">Stick-It</span> is a sticky-note corkboard web app. It is operated by <strong>Jonathan Zachevsky</strong>, an individual in <strong>Israel</strong> (\"we\", \"<span class=\"bw\">Stick-It</span>\"). No company has been formed. Public postal address: <mark class=\"todo\">[PUBLIC POSTAL ADDRESS NOT CONFIGURED]</mark>. Support contact: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>.</p>\n<h2>2. Acceptance of these terms</h2>\n<p>By creating an account, or by using <span class=\"bw\">Stick-It</span> as a guest, you agree to these terms and acknowledge the <a href=\"privacy.html\">Privacy Policy</a>. If you do not agree, do not use <span class=\"bw\">Stick-It</span>. If you use <span class=\"bw\">Stick-It</span> for an organisation, you confirm you may agree on its behalf.</p>\n<h2>3. Who may use <span class=\"bw\">Stick-It</span>, and young people</h2>\n<p><span class=\"bw\">Stick-It</span> asks \"How old are you?\" before it offers sign-in. We keep only the result (adult, teen or child), not your date of birth.</p>\n<ul><li><strong>18 or older (adult):</strong> you may use <span class=\"bw\">Stick-It</span>, with or without an account.</li><li><strong>13 to 17 (teen):</strong> you may use <span class=\"bw\">Stick-It</span>. Your account starts with conservative settings: no product-update e-mails, share links that show no profile details by default, and no public profile. Because you are under 18, a parent or guardian should know you use it. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED: Israeli rules on minors and guardian consent]</mark></li><li><strong>Under 13 (child):</strong> you may use <span class=\"bw\">Stick-It</span> <strong>as a guest only</strong>, with your boards kept on your own device. A cloud account, sharing and other cloud features are not available until a parent or guardian has given verified consent. <strong>That verified-consent mechanism does not exist yet</strong>, so for now children cannot use accounts.</li></ul>\n<p>We do not market to anyone under 18. The <a href=\"young-people.html\">Young people and parents</a> page explains this in plain language.</p>\n<h2>4. Your account</h2>\n<ul><li>Keep your Google or GitHub sign-in secure. You are responsible for activity under your account.</li><li>Give accurate profile details and do not impersonate anyone.</li><li>You can delete your account at any time in Account settings.</li></ul>\n<h2>5. Your content and the licence you give us</h2>\n<ul><li><strong>You own your content</strong> (notes, pictures, voice memos, videos, boards, profile information). <span class=\"bw\">Stick-It</span> does not claim ownership of it.</li><li><strong>A limited licence.</strong> You give us permission to host, store, back up, copy, transmit and display your content <strong>only as needed to run <span class=\"bw\">Stick-It</span> for you</strong>: sync it, show it to the people you share it with, and keep it safe. The permission ends when you delete the content or your account, except for copies that remain in backups or logs until they expire. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED]</mark></li><li><strong>You are responsible for it.</strong> You confirm that you have the right to upload and share it and that it does not infringe others' rights or break the law.</li></ul>\n<h2>6. Acceptable use</h2>\n<p>Do not use <span class=\"bw\">Stick-It</span> to: upload or share content that is illegal, that sexually exploits or endangers children, that harasses, threatens or incites violence, that invades others' privacy, that infringes intellectual-property rights, or that contains malware; probe, scrape or overload the service; get around access controls, limits or the age step; or help anyone else do these things. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED: complete list]</mark></p>\n<h2>7. Sharing, public links and collaboration</h2>\n<ul><li>A <strong>share link</strong> shows what you shared to <strong>anyone who has the link</strong>, without an account. Links stay active until you turn them off. A <strong>snapshot</strong> link shows a frozen copy. A <strong>live board</strong> link shows the whole board, read-only, as it changes.</li><li>What a link shows about you (name, picture, bio) is what you chose in Account settings when the link was created.</li><li><strong>Collaborators</strong> you invite can see, and with an editor role change, the board. Decide carefully who you invite.</li><li>People you send a link to can keep copies. We cannot take back what others have saved.</li></ul>\n<h2>8. Content we may remove, and suspension</h2>\n<p>We may remove or disable content or links, or suspend or end accounts, if we reasonably believe these terms or the law are broken, to respond to a valid complaint or legal request, or to protect people or the service. Where we can, we will tell you why. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED: notice and appeal process]</mark></p>\n<h2>9. Copyright complaints</h2>\n<p>If you believe something on <span class=\"bw\">Stick-It</span> infringes your copyright, use the <a href=\"copyright.html\">Copyright page</a>. We handle notices under the process described there. <span class=\"bw\">Stick-It</span> has <strong>not</strong> registered a U.S. DMCA designated agent, and Israeli law has no identical safe-harbour mechanism, so the page describes our own good-faith process. We may end the accounts of people who repeatedly infringe. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED]</mark></p>\n<h2>10. Privacy</h2>\n<p>How we handle personal data is described in the <a href=\"privacy.html\">Privacy Policy</a>. It forms part of these terms for the purposes of explaining that handling.</p>\n<h2>11. Availability and backups</h2>\n<p><span class=\"bw\">Stick-It</span> is provided while it is still being developed. It may change, be interrupted or have errors. <strong>We do not guarantee that nothing will be lost.</strong> Keep your own copy of anything important: use Export in Settings or Account settings. Guest boards live only in your browser and can be lost if you clear browser data.</p>\n<h2>12. Plans and payments</h2>\n<p>Today <span class=\"bw\">Stick-It</span> has <strong>no paid plan and takes no payment.</strong> If paid plans are added, the price, billing period, automatic renewal, how to cancel and any refund rules will be shown next to the purchase button before you pay, and these terms will be updated. See <code>docs/legal/israel-payments-checklist.md</code>.</p>\n<h2>13. Ending your use</h2>\n<p>You can stop using <span class=\"bw\">Stick-It</span> and delete your account at any time. We may end or change the service; if we end it we will try to give notice and a chance to export. When an account is deleted its content is removed as the Privacy Policy describes.</p>\n<h2>14. Warranty disclaimer</h2>\n<p><span class=\"bw\">Stick-It</span> is provided \"as is\" and \"as available\" to the extent the law allows. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED: wording for Israeli law. Rights that cannot be waived by contract, including consumer rights, are not affected by anything in these terms.]</mark></p>\n<h2>15. Limitation of liability</h2>\n<p>To the extent the law allows, we are not liable for indirect or consequential loss, or for loss of data you did not back up. Nothing in these terms limits liability that cannot be limited by law, including mandatory consumer protections. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED: this section needs a lawyer to write it for Israel]</mark></p>\n<h2>16. Indemnity</h2>\n<p>If your content or your breach of these terms causes a third-party claim against us, you agree to help us deal with it to the extent the law allows. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED: consider whether to include this at all for consumers]</mark></p>\n<h2>17. Governing law and courts (proposed)</h2>\n<p><strong>Proposed:</strong> the laws of the <strong>State of Israel</strong>, with the competent courts of the <strong>Tel Aviv-Jaffa district</strong> having jurisdiction, <strong>subject to any mandatory consumer-protection rules that give you other rights</strong>. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED: this is a proposal chosen by the owner, not advice, and has not been checked by a lawyer]</mark></p>\n<h2>18. Changes to these terms</h2>\n<p>We may update these terms. We will post the new version and its date and tell account holders in the app about material changes. Continuing to use <span class=\"bw\">Stick-It</span> after a change means you accept it. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED]</mark></p>\n<h2>19. Termination for breach</h2>\n<p>We may suspend or end your access if you seriously or repeatedly break these terms. Sections that by their nature should survive ending (for example copyright complaints, limits of liability and governing law) continue to apply.</p>\n<h2>20. General</h2>\n<p>If part of these terms cannot be enforced, the rest still applies. Not enforcing a term at once does not waive it. You may not transfer your account to someone else. Where Hebrew and English versions differ, see the note on the Hebrew page. <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED: which version governs]</mark></p>\n<h2>21. Contact</h2>\n<p>Operator: Jonathan Zachevsky, Israel. Support: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>. Privacy: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>. Copyright: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>. Public postal address: <mark class=\"todo\">[PUBLIC POSTAL ADDRESS NOT CONFIGURED]</mark>.</p>"}, "copyright": {"title": "Copyright / DMCA", "file": "copyright.html", "html": "<h1>Copyright / DMCA (DRAFT)</h1>\n<blockquote class=\"draftNote\"><p><strong>Development-only page. Not final.</strong> <span class=\"bw\">Stick-It</span> has <strong>not</strong> registered a DMCA designated agent. Nothing below is a registered designation until the owner completes the steps in <code>docs/legal/dmca-readiness.md</code> and sets <code>dmcaRegistered</code> to <code>true</code> in <code>js/legal-config.js</code>. The complaint form on this page stays hidden until then.</p></blockquote>\n<h2>Reporting copyright infringement</h2>\n<p><span class=\"bw\">Stick-It</span> lets people create, paste, upload and share content. Users are responsible for making sure they have the rights or permission needed for what they add. <span class=\"bw\">Stick-It</span> does not proactively inspect every private board for copyright ownership. If a valid copyright complaint is received, <span class=\"bw\">Stick-It</span> may investigate and may restrict or remove the reported material where appropriate. This page does not limit any responsibility <span class=\"bw\">Stick-It</span> has under the law. If you are a copyright owner (or authorised to act for one) and you believe content on <span class=\"bw\">Stick-It</span> infringes your copyright, please send a notice to the general copyright contact below. No DMCA designated agent is registered yet.</p>\n<h3>Where to send a copyright notice</h3>\n<p>E-mail: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>. This is <span class=\"bw\">Stick-It</span>'s general copyright contact only. It is <strong>not</strong> a registered DMCA designated agent (see below), and must not be described as one until registration is complete. Postal address: <mark class=\"todo\">[PUBLIC POSTAL ADDRESS NOT CONFIGURED]</mark>.</p>\n<h3>DMCA Designated Agent</h3>\n<div class=\"tableWrap\"><table><tbody><tr><th scope=\"row\">Service provider</th><td><mark class=\"todo\">[OWNER INPUT REQUIRED: legal name of the service provider]</mark></td></tr><tr><th scope=\"row\">Name / role</th><td><mark class=\"todo\">[OWNER INPUT REQUIRED: agent name or role]</mark></td></tr><tr><th scope=\"row\">Organization</th><td><mark class=\"todo\">[OWNER INPUT REQUIRED]</mark></td></tr><tr><th scope=\"row\">Mailing address</th><td><mark class=\"todo\">[OWNER INPUT REQUIRED: street address, not a P.O. box unless permitted]</mark></td></tr><tr><th scope=\"row\">Telephone</th><td><mark class=\"todo\">[OWNER INPUT REQUIRED]</mark></td></tr><tr><th scope=\"row\">E-mail</th><td><mark class=\"todo\">[OWNER INPUT REQUIRED]</mark></td></tr></tbody></table></div>\n<h3>What your notice must include</h3>\n<p>A written notice should contain: (1) your physical or electronic signature; (2) identification of the copyrighted work you say was infringed; (3) identification of the material and <strong>where it is</strong> (for <span class=\"bw\">Stick-It</span>, the share link or page address); (4) your contact details (address, telephone, e-mail); (5) a statement that you have a good-faith belief the use is not authorised by the copyright owner, its agent or the law; and (6) a statement, <strong>under penalty of perjury</strong>, that the information is accurate and that you are the owner or authorised to act for the owner.</p>\n<p>Please be accurate. Knowingly misrepresenting that material is infringing can carry legal consequences.</p>\n<h3>What happens next</h3>\n<p>We review notices. If a notice is complete and appears valid we may remove or disable the material and tell the person who uploaded or shared it. <mark class=\"todo\">[OWNER INPUT REQUIRED / LEGAL REVIEW: exact process and timing]</mark></p>\n<h3>Counter-notice</h3>\n<p>If your content was removed and you believe that was a mistake or that you have the right to use it, you may send a counter-notice to the same agent. <mark class=\"todo\">[OWNER INPUT REQUIRED / LEGAL REVIEW: counter-notice contents, 10 to 14 business-day restoration process]</mark></p>\n<h3>Repeat infringers</h3>\n<p><mark class=\"todo\">[OWNER INPUT REQUIRED / LEGAL REVIEW: repeat-infringer policy. A written policy and its reasonable implementation are a condition of the DMCA safe harbour.]</mark></p>\n<h3>Other complaints</h3>\n<p>For privacy requests see the <a href=\"privacy.html\">Privacy Policy</a>. For other abuse, use the <strong>Report</strong> link on any shared page.</p>"}, "young": {"title": "Young people and parents", "file": "young-people.html", "html": "<h1>Young people and parents (DRAFT)</h1>\n<blockquote class=\"draftNote\"><p><strong>Draft for review. Not legal advice and not final.</strong> <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED]</mark></p></blockquote>\n<p><span class=\"bw\">Stick-It</span> asks \"How old are you?\" before it offers sign-in. We keep only the result, never your date of birth.</p>\n<h2>What each age group can do</h2>\n<div class=\"tableWrap\"><table><thead><tr><th scope=\"col\">Age</th><th scope=\"col\">What happens</th></tr></thead><tbody><tr><td><strong>18 or older</strong></td><td>Full use, with or without an account.</td></tr><tr><td><strong>13 to 17</strong></td><td>Accounts are allowed with conservative settings: no product-update e-mail, share links show no profile details by default, no public profile.</td></tr><tr><td><strong>Under 13</strong></td><td>Guest use only. Boards stay in the browser on that device. A cloud account, sharing and other cloud features need verified consent from a parent or guardian.</td></tr></tbody></table></div>\n<h2>Parental consent: honest status</h2>\n<p>A verified parental-consent process <strong>does not exist yet</strong>. Until it does, children under 13 can use <span class=\"bw\">Stick-It</span> only as guests. We will not pretend a click or an e-mail address is verified consent.</p>\n<p>If a child's cloud account was created anyway (for example by getting around the age step), the account is <strong>restricted and kept pending</strong>: cloud features are blocked, we do not delete it automatically, and a parent or guardian can ask us to delete it. Accounts that never finish the age step and have nothing in them are cleaned up by a scheduled job once the owner turns that job on.</p>\n<h2>What we do not do for young people</h2>\n<ul><li>No marketing e-mail to anyone under 18.</li><li>No public profiles by default.</li><li>No advertising and no tracking. (There is no product analytics today; if that ever changes, the Privacy Policy is updated first and analytics never read notes, comments, searches or private media.) <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED]</mark></li><li>No collection of a date of birth.</li></ul>\n<h2>For parents and guardians</h2>\n<p>To ask what we hold about a child, or to ask us to delete a child's account, write to <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>. Please tell us which sign-in account it is. We may need to confirm that you are the parent or guardian.</p>\n<p>See also the <a href=\"privacy.html\">Privacy Policy</a> and <a href=\"terms.html\">Terms</a>.</p>"}, "storage": {"title": "Storage notice", "file": "storage.html", "html": "<h1>Storage notice (DRAFT)</h1>\n<blockquote class=\"draftNote\"><p><strong>Draft for review.</strong> <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED]</mark></p></blockquote>\n<p><span class=\"bw\">Stick-It</span> currently does not set its own browser cookies. Instead, it uses browser storage such as local storage and IndexedDB for guest boards, preferences, cached board data and session-related information. These technologies serve similar persistence purposes but are technically different from cookies. They are used because the app needs them to work:</p>\n<div class=\"tableWrap\"><table><thead><tr><th scope=\"col\">What</th><th scope=\"col\">Why</th></tr></thead><tbody><tr><td>Your guest boards and notes</td><td>So your work is still there next time</td></tr><tr><td>Settings (theme, fonts, preferences)</td><td>To remember your choices</td></tr><tr><td>Cutouts you make as a guest (small transparent pictures kept in the browser IndexedDB) and a note that you have seen the cutout tips</td><td>So your cutouts are still there next time</td></tr><tr><td>The result of the age step (adult or teen, with a timestamp, never a birth date). A short-lived copy is used for about an hour while you sign in; a longer-lived copy is trusted for up to 90 days on a browser where you have signed in (after that it is ignored; the old entry stays until it is replaced or you clear your browser data)</td><td>So you are not asked again each time you sign in</td></tr><tr><td>A pending board invitation, kept in the tab's session storage only until you finish signing in</td><td>So an invitation survives the sign-in step</td></tr><tr><td>When signed in: your sign-in session and a cached copy of your boards</td><td>To sign you in and show boards quickly or offline</td></tr></tbody></table></div>\n<p><span class=\"bw\">Stick-It</span> does not currently use advertising or session-recording tools. Product analytics may be introduced to understand how the service is used, such as counts of accounts, boards, object types, feature use, errors and performance. Analytics would not collect content such as note text, comment text, search queries, private board text or private photos, videos and audio. If analytics go live, this notice and the Privacy Policy are updated at the same time. Embedded video providers, payment processing or analytics may use cookies or similar technologies in the future, and this notice would be updated if that changes.</p>\n<p>The storage listed above is strictly needed to provide what you asked for. Clearing your browser data removes it, and signing out removes the signed-in copy. Guest boards are not sent to us; clearing browser data deletes them for good unless you exported them.</p>\n<p>See the <a href=\"privacy.html\">Privacy Policy</a>.</p>"}, "accessibility": {"title": "Accessibility statement", "file": "accessibility.html", "html": "<h1>Accessibility statement (DRAFT)</h1>\n<blockquote class=\"draftNote\"><p><strong>Draft for review. This is not a certificate of conformance.</strong> <mark class=\"todo\">[LEGAL REVIEW RECOMMENDED]</mark></p></blockquote>\n<p>Last updated: 2026-10-01</p>\n<p><span class=\"bw\">Stick-It</span> is a personal project by Jonathan Zachevsky, Israel. <span class=\"bw\">Stick-It</span> aims to meet <strong>WCAG 2.2 Level AA</strong> as its product-development accessibility target. Where Israeli accessibility requirements apply to <span class=\"bw\">Stick-It</span>, we also aim to meet the applicable requirements of Israeli Standard SI 5568 and the Equal Rights for Persons with Disabilities regulations. These are separate references: SI 5568 is not simply the same thing as WCAG 2.2. <strong>We have not been audited by an accredited accessibility specialist and do not claim certification or verified conformance.</strong></p>\n<h2>What we have done</h2>\n<ul><li>Keyboard use: dialogs trap and restore focus, <code>N</code> creates a note, visible focus rings.</li><li>Skip link, labelled controls, reduced-motion support.</li><li>Colour contrast checked for the main text and button colours in light and dark themes.</li><li>Self-hosted fonts including Hebrew and Arabic scripts; Hebrew pages are right-to-left.</li></ul>\n<h2>Known limitations</h2>\n<ul><li>Notes are positioned by dragging. Keyboard movement exists for a selected note, but selecting and arranging notes without a pointer is limited.</li><li>Voice-memo and video controls have not been tested with assistive technology.</li><li>Not every status message is announced to screen readers.</li><li>Not tested with NVDA, JAWS or VoiceOver by disabled users, and not tested beyond 200% zoom.</li><li>Not yet tested on physical phones and tablets with assistive technology.</li><li>Pile browsing, embedded video and the in-app legal reader are new and have only had developer checks, not testing with assistive technology.</li></ul>\n<h2>Contact</h2>\n<p>If you cannot use part of <span class=\"bw\">Stick-It</span>, tell us what you tried, what stopped you, which browser you use and, if you know it, which assistive technology: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>. We will try to answer and to offer another way to do what you need. The accessibility coordinator and the full required statement items are open owner actions: see <code>docs/legal/israel-accessibility.md</code>.</p>"}}, "he": {"privacy": {"title": "מדיניות פרטיות", "file": "privacy.html", "html": "<h1>מדיניות פרטיות (טיוטה)</h1>\n<blockquote class=\"draftNote\"><p><strong>טיוטה לבדיקה. אין זו ייעוץ משפטי והיא אינה סופית.</strong> הטקסט מתאר מה ש-<span class=\"bw\">Stick-It</span> עושה בפועל כיום, ולא נבדק על ידי עורך דין. פריטים המסומנים <code><mark class=\"todo\">[נדרש מידע מהבעלים: ...]</mark></code> או <code><mark class=\"todo\">[מומלץ סקירה משפטית]</mark></code> עדיין דורשים השלמה.</p></blockquote>\n<p>עדכון אחרון: <code>2026-10-01</code> (גרסת טיוטה <code>2026-10-01-draft</code>)</p>\n<h2>1. מי מפעיל את <span class=\"bw\">Stick-It</span></h2>\n<p><span class=\"bw\">Stick-It</span> מופעלת על ידי <strong>Jonathan Zachevsky</strong>, יחיד בישראל. לא הוקמה חברה. כתובת דואר ציבורית: <mark class=\"todo\">[כתובת דואר ציבורית לא הוגדרה]</mark>. פנייה בנושאי פרטיות: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>.</p>\n<h2>2. בקצרה</h2>\n<ul><li><strong>כאורח</strong> אפשר להשתמש בלי חשבון. הלוחות נשארים בדפדפן שלכם, ואיננו מקבלים אותם.</li><li><strong>עם חשבון</strong> אנו שומרים את פרטי החשבון ואת הלוחות, הפתקים, התמונות, ההקלטות והסרטונים שלכם, כדי שילוו אתכם בין מכשירים.</li><li><strong>קישורי שיתוף</strong> מציגים את מה שבחרתם לשתף לכל מי שמחזיק בקישור.</li><li>כיום <strong>אין</strong> פרסום והקלטת מסך, ואיננו משתמשים כרגע באנליטיקת מוצר. איננו מוכרים מידע אישי. ייתכן שתוכנס בעתיד אנליטיקת מוצר (ראו סעיף 9); אם כן, מדיניות זו תעודכן קודם, והאנליטיקה לעולם לא תקרא פתקים, תגובות, חיפושים או מדיה פרטית.</li><li><strong>צעירים:</strong> ילדים מתחת לגיל 13 יכולים להשתמש רק כאורחים עד שתהיה הסכמת הורים מאומתת. ראו סעיף 14.</li></ul>\n<h2>3. איזה מידע נאסף ולמה</h2>\n<div class=\"tableWrap\"><table><thead><tr><th scope=\"col\">מה</th><th scope=\"col\">דוגמאות</th><th scope=\"col\">למה</th></tr></thead><tbody><tr><td><strong>פרטי התחברות</strong> (Google, GitHub או קוד בדוא\"ל)</td><td>כתובת דוא\"ל, שם או שם משתמש, כתובת תמונת פרופיל, מזהה אצל הספק</td><td>ליצור ולאבטח חשבון</td></tr><tr><td><strong>קבוצת גיל</strong></td><td>רק תוצאת שלב הגיל: בוגר, נער/ה או ילד/ה, מועד האישור, ולילדים סטטוס הסכמת הורים. <strong>תאריך הלידה, והחודש והשנה שהקלדתם, אינם נשלחים אלינו ואינם נשמרים.</strong></td><td>להחיל הגנות מתאימות לגיל</td></tr><tr><td><strong>גרסאות מסמכים</strong></td><td>גרסת התנאים והמדיניות שהוצגה לכם</td><td>לתעד מה נאמר לכם</td></tr><tr><td><strong>פרופיל</strong></td><td>שם תצוגה, שם משתמש אופציונלי, אודות קצר, תמונה</td><td>להציג מי אתם באפליקציה ובקישורים</td></tr><tr><td><strong>העדפות</strong></td><td>איך תופיעו בקישורים, גופן, צבע פתק, והאם תרצו דוא\"ל עדכוני מוצר (<strong>כבוי כברירת מחדל ולא זמין מתחת לגיל 18</strong>)</td><td>ליישם את בחירותיכם</td></tr><tr><td><strong>התוכן שלכם</strong></td><td>לוחות, פתקים, תמונות, הקלטות, סרטונים</td><td>לספק את השירות</td></tr><tr><td><strong>נתוני שיתוף פעולה</strong></td><td>לוחות שאתם חברים בהם ותפקידכם; הזמנות</td><td>לאפשר שיתוף לוחות</td></tr><tr><td><strong>תגובות וסקירה</strong></td><td>טקסט התגובות שאתם מוסיפים לפריט, מי כתב ומתי; מצב סקירה בפריט (נדרשים שינויים / מוכן לסקירה) עם נימוק קצר אופציונלי</td><td>לאפשר לשותפים לדון בפריט. גלוי לכל מי שנמצא בלוח</td></tr><tr><td><strong>נוכחות</strong> (לא נשמר)</td><td>בזמן שלוח משותף פתוח: שם התצוגה שלכם והפריט שאתם עורכים או מזיזים</td><td>להציג מי נמצא ולמנוע עריכה של אותו פתק בידי שניים בו-זמנית. קיים רק כל עוד הדף פתוח ואינו נשמר</td></tr><tr><td><strong>גזירות (Cutouts)</strong></td><td>תמונת הגזירה שיצרתם מתמונה (נשמרת כמו כל תמונה). <strong>גזירות נוצרות במכשיר שלכם: התמונה אינה נשלחת לשום שירות לצורך כך</strong></td><td>להציג תמונה כמדבקה</td></tr><tr><td><strong>קישורי שיתוף</strong></td><td>עותק של מה ששיתפתם ופרטי הפרופיל שבחרתם להציג. כתובת הקישור הסודית נשמרת רק כגיבוב חד-כיווני</td><td>שהקישורים יעבדו ויהיה אפשר לכבותם</td></tr><tr><td><strong>דיווחים</strong></td><td>דיווחי תוכן או זכויות יוצרים שאתם שולחים</td><td>לטפל בהתעללות ובתלונות</td></tr><tr><td><strong>נתונים טכניים ואבטחה</strong></td><td>נתוני בקשה רגילים (כתובת IP, סוג דפדפן, זמן) מעובדים אצל ספקי האירוח ומסד הנתונים</td><td>לספק ולהגן על השירות</td></tr></tbody></table></div>\n<p>כיום <span class=\"bw\">Stick-It</span> אינה אוספת מספר טלפון, כתובת דואר, פרטי תשלום, אנשי קשר, מיקום מדויק או תאריך לידה.</p>\n<p><strong>תכונות אפשריות בעתיד.</strong> ייתכן ש-<span class=\"bw\">Stick-It</span> תוסיף בעתיד תכונות אופציונליות שידרשו מידע נוסף, כגון פרטי תשלום, מספר טלפון, אנשי קשר או מיקום. אם זה יקרה, מדיניות זו וכל הודעה רלוונטית במוצר יעודכנו לפני שהתכונות יאספו את המידע. בקווים כלליים, ורק אם תכונות כאלה ייבנו:</p>\n<ul><li><strong>מספר טלפון:</strong> אולי לקודי אימות חד-פעמיים או לשחזור חשבון. הודעות אופציונליות יישלחו רק כשהחוק מתיר ורק אם הסכמתם להן במפורש; מסירת מספר טלפון אינה בפני עצמה הסכמה לשיווק.</li><li><strong>פרטי תשלום:</strong> פרימיום עשוי להשתמש בעתיד בספק תשלומים חיצוני. נשאף שמספרי כרטיס מלאים יטופלו אצל הספק ולא יישמרו ב-<span class=\"bw\">Stick-It</span>. כיום אין ספק תשלומים פעיל.</li><li><strong>אנשי קשר:</strong> אולי כדי לעזור לכם להזמין אנשים ללוח. נבקש הרשאה מפורשת, נעדיף אנשי קשר שתבחרו, ולא נעלה בשקט ספר כתובות שלם אלא אם זה באמת הכרחי.</li><li><strong>מיקום:</strong> אולי לתכונות אופציונליות כגון סיכות מפה או פתקים הקשורים למקום. שום דבר ב-<span class=\"bw\">Stick-It</span> כיום אינו צריך את המיקום שלכם, גם לא לשימוש בלי רשת.</li></ul>\n<h2>4. האם חובה למסור</h2>\n<p>אין צורך בחשבון לשימוש כאורח. פתיחת חשבון דורשת התחברות Google או GitHub ושלב הגיל; בלעדיהם איננו יכולים להציע חשבון. כל השאר אופציונלי.</p>\n<h2>5. הודעה בעת איסוף</h2>\n<p>מדיניות זו היא ההודעה בעת איסוף: מי מפעיל את <span class=\"bw\">Stick-It</span> (סעיף 1), מה נאסף ולמה (סעיף 3), האם חובה למסור (סעיף 4) ומי מקבל (סעיף 7). מסך ההתחברות מפנה אליה ואל התנאים לפני שממשיכים. אפשר גם להשתמש ב-<span class=\"bw\">Stick-It</span> כאורח בלי להתחבר. בהתחברות בדוא\"ל אנו מקבלים את הכתובת ו-Supabase שולחת לכם קוד חד-פעמי; <span class=\"bw\">Stick-It</span> אינה שומרת את הקוד או סיסמה.</p>\n<h2>6. איך אנו משתמשים במידע</h2>\n<p>כדי לספק, לאבטח ולתחזק את <span class=\"bw\">Stick-It</span>; לסנכרן לוחות; להציג שם, תמונה ואודות בקישורים <strong>רק אם בחרתם</strong>; להחיל הגנות לפי גיל; להשיב לדיווחים ולבקשות משפטיות; ולשמור על אמינות. איננו משתמשים בתוכן לאימון בינה מלאכותית, לא מוכרים אותו ולא משתמשים בו לפרסום. <mark class=\"todo\">[נדרש מידע מהבעלים: לאשר שזה משקף את הכוונה]</mark></p>\n<p><strong>גישה לתוכן שלכם.</strong> <span class=\"bw\">Stick-It</span> אינה בודקת באופן שגרתי את התוכן הפרטי שלכם. הלוחות נשמרים בתשתית הענן שלנו, ולכן ייתכנה גישה מוגבלת כשהיא נחוצה כדי להפעיל ולאבטח את השירות, לספק תמיכה שביקשתם, לבדוק תוכן שדווח או שיש חשד סביר שהוא מפר את החוק או את התנאים, לאכוף את התנאים, או לקיים חובה חוקית. עיון שגרתי בתוכן פרטי אינו חלק מאופן הפעולה של <span class=\"bw\">Stick-It</span>.</p>\n<p><strong>אחריות לתוכן.</strong> אתם אחראים לוודא שמה שאתם יוצרים, מעלים או משתפים עומד בדין ובתנאים. כשמדווחים על הפרה או שיש חשד סביר לה, <span class=\"bw\">Stick-It</span> רשאית לחקור ולהגביל או להסיר תוכן או חשבון כשמתאים. <mark class=\"todo\">[מומלץ סקירה משפטית]</mark></p>\n<h2>7. מי מקבל מידע</h2>\n<ul><li><strong>ספקי שירות:</strong> <strong>Supabase</strong> (מסד נתונים, התחברות, אחסון קבצים, פונקציות שרת) ו-<strong>GitHub</strong> (אירוח האתר ב-GitHub Pages).</li><li><strong>ספקי התחברות.</strong> Google ו-GitHub יודעים שאתם משתמשים ב-<span class=\"bw\">Stick-It</span>.</li><li><strong>כל מי שמחזיק בקישור</strong> שיצרתם.</li><li><strong>חברים אחרים בלוחות משותפים</strong> רואים את תוכן הלוח ואת שם התצוגה שלכם.</li><li><strong>רשויות,</strong> כשאנו מחויבים בדין או כדי להגן על בטיחות או זכויות. <mark class=\"todo\">[נדרש מידע מהבעלים: מדיניות הליך משפטי]</mark></li></ul>\n<p>איננו מוכרים מידע אישי ואיננו משתפים אותו לצורכי פרסום.</p>\n<h2>8. דוא\"ל שיווקי</h2>\n<p>דוא\"ל עדכוני מוצר <strong>כבוי כברירת מחדל</strong>, רק לבוגרים שהפעילו אותו, ולעולם לא נשלח למי שמתחת לגיל 18. כל הודעה חייבת לכלול קישור הסרה בלחיצה אחת, זהות השולח ופרטי קשר תקפים. <strong>כיום לא נשלח דוא\"ל שיווקי.</strong> הוא נשאר מושבת עד שתוגדר כתובת דואר ציבורית ושולח. <mark class=\"todo\">[מומלץ סקירה משפטית: סעיף 30א לחוק התקשורת]</mark></p>\n<h2>9. אחסון בדפדפן, עוגיות ואנליטיקה</h2>\n<p>כיום <span class=\"bw\">Stick-It</span> אינה מציבה עוגיות משלה. במקום זאת היא משתמשת באחסון הדפדפן, כגון אחסון מקומי ו-IndexedDB, ללוחות אורח, העדפות, עותק מקומי של לוחות ומידע הקשור להפעלה. טכנולוגיות אלה משרתות מטרות שמירה דומות אך שונות טכנית מעוגיות. האחסון נחוץ לפעולת האפליקציה. ראו את <a href=\"storage.html\">הודעת האחסון</a>.</p>\n<p><strong>תוכן של צד שלישי.</strong> אם תבחרו להציג קישור לסרטון נתמך כסרטון מוטמע, הדפדפן שלכם יפנה לשרתי ספק הסרטונים כדי להפעיל אותו, והספק עשוי להשתמש בעוגיות או בטכנולוגיות דומות לפי מדיניותו. קישור שנשאר קישור רגיל אינו פונה לאף גורם עד שתפתחו אותו.</p>\n<p><strong>שינויים אפשריים בעתיד.</strong> אנליטיקת מוצר (למשל ספירת חשבונות, לוחות, סוגי עצמים, שימוש בתכונות, שגיאות וביצועים, ולעולם לא תוכן הפתקים, התגובות, החיפושים או המדיה הפרטית), עיבוד תשלומים או ספקי הטמעה אחרים עשויים להשתמש בעתיד בעוגיות או בטכנולוגיות דומות. אם זה יקרה, מדיניות זו והודעת האחסון יעודכנו יחד.</p>\n<h2>10. עיבוד בינלאומי</h2>\n<p>ספקינו עשויים לעבד מידע מחוץ לישראל. <mark class=\"todo\">[נדרש מידע מהבעלים: אזור פרויקט Supabase ומאיפה GitHub Pages משרתת]</mark>. חלים כללי העברת מידע אל מחוץ לישראל. <mark class=\"todo\">[מומלץ סקירה משפטית: בסיס ההעברה]</mark></p>\n<h2>11. כמה זמן נשמר</h2>\n<div class=\"tableWrap\"><table><thead><tr><th scope=\"col\">מידע</th><th scope=\"col\">נשמר</th></tr></thead><tbody><tr><td>חשבון, פרופיל, העדפות, לוחות, קבצים</td><td>עד שתמחקו אותם או את החשבון</td></tr><tr><td>פתקים שמחקתם</td><td>מסומנים כמחוקים לצורך ביטול, ואז מוסרים לצמיתות על ידי משימת ניקוי יומית לאחר שנמחקו יותר מ-30 יום</td></tr><tr><td>קבצים שאינם בשימוש</td><td>מוסרים באותה משימה יומית לאחר תקופת חסד של 14 יום</td></tr><tr><td>הרשמות נטושות (חשבון שלא סיים את שלב הגיל ואין בו דבר)</td><td>מוסרות באותה משימה יומית לאחר 7 ימים</td></tr><tr><td>קישורי שיתוף</td><td>עד שתכבו אותם או תמחקו את החשבון</td></tr><tr><td>תגובות ומצבי סקירה</td><td>עד שיימחקו, או שהפריט, הלוח או החשבון יימחקו</td></tr><tr><td>דיווחים</td><td><mark class=\"todo\">[נדרש מידע מהבעלים: משך שמירה]</mark></td></tr><tr><td>יומני ספקים וגיבויים</td><td>בשליטת Supabase ו-GitHub. <mark class=\"todo\">[נדרש מידע מהבעלים]</mark></td></tr></tbody></table></div>\n<h2>12. מחיקת חשבון וקבלת עותק</h2>\n<p><strong>באפליקציה:</strong> הגדרות חשבון, מחיקת חשבון (הקלידו DELETE). הפעולה מסירה את הפרופיל וההגדרות, את הלוחות שבבעלותכם על כל תוכנם, את הקבצים והתמונה, את קישורי השיתוף (הם מפסיקים לעבוד מיד), הזמנות וחברויות, ואז את חשבון ההתחברות.</p>\n<p><strong>לא מוסר:</strong> פתקים שהוספתם ללוח של אחר (נשארים, ללא שמכם), דיווחים ששלחתם, מידע ביומני ספקים וגיבויים עד פקיעתם, וחשבון Google או GitHub וההרשאה שנתתם (בטלו אצלם). איננו טוענים למחיקה מיידית של גיבויים.</p>\n<p><strong>עותק מהמידע:</strong> הגדרות חשבון, נתונים ופרטיות, ייצוא הלוחות שלי. הוא עדיין אינו כולל קבצי הקלטה וסרטון. לשאר פנו אל <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>.</p>\n<h2>13. הזכויות שלכם</h2>\n<p>לפי דיני הפרטיות בישראל ייתכן שיש לכם זכות לעיין במידע שאנו מחזיקים עליכם ולבקש לתקן או למחוק אותו. כתבו אל <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>. אפשר גם לפנות לרשות להגנת הפרטיות. <mark class=\"todo\">[מומלץ סקירה משפטית: הזכויות והמועדים המדויקים לאחר תיקון 13]</mark></p>\n<h2>14. ילדים ובני נוער</h2>\n<p><span class=\"bw\">Stick-It</span> היא שירות לקהל כללי. איננו משווקים למי שמתחת לגיל 18.</p>\n<ul><li><strong>בוגרים (18+):</strong> שימוש מלא.</li><li><strong>בני נוער (13-17):</strong> חשבון מותר עם ברירות מחדל שמרניות: ללא דוא\"ל שיווקי, קישורים ללא פרטי פרופיל כברירת מחדל, ללא פרופיל ציבורי.</li><li><strong>ילדים (מתחת ל-13):</strong> שימוש כאורח במכשיר בלבד. חשבון ענן אינו זמין עד שהורה או אפוטרופוס נתנו הסכמה מאומתת. <strong>המנגנון עדיין לא קיים.</strong> אם קיים חשבון של ילד (למשל שנוצר בעקיפת שלב הגיל), אנו מגבילים תכונות ענן ומשאירים אותו בהמתנה; איננו מוחקים אותו אוטומטית.</li></ul>\n<p><strong>מידע גיל כוזב.</strong> אם נקבע באופן סביר שחשבון השתמש בפרטי גיל כוזבים כדי לעקוף הגנות גיל, ייתכן שנשהה או נמחק את החשבון ואת נתוני הענן הקשורים אליו, בכפוף לדין החל ולכל שמירה שאנו מחויבים בה בחוק. נתוני חשבון פעילים עשויים להימחק; יומנים וגיבויים אצל הספקים עשויים להישאר זמן מה; <span class=\"bw\">Stick-It</span> אינה שומרת תוכן שנמחק רק לשימוש עתידי. <mark class=\"todo\">[מומלץ סקירה משפטית: יש לשמור עקביות עם דף צעירים והורים]</mark></p>\n<p>להורים ואפוטרופוסים: <a href=\"young-people.html\">צעירים והורים</a>. <mark class=\"todo\">[מומלץ סקירה משפטית]</mark></p>\n<h2>15. אבטחה</h2>\n<p>לוחות וקבצים מאוחסנים במסד נתונים ובאחסון פרטיים עם כללי גישה לכל משתמש; מדיה מועברת בקישורים קצרי חיים. קישורי שיתוף עובדים לכל מי שמחזיק בהם. אין מערכת מאובטחת לחלוטין. לדיווח על בעיית אבטחה: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>.</p>\n<h2>16. החלטות אוטומטיות</h2>\n<p>איננו מקבלים החלטות עליכם בפרופיילינג או באופן אוטומטי שיש להן השלכה משפטית או מהותית דומה.</p>\n<h2>17. רישום ברשות להגנת הפרטיות</h2>\n<p>האם יש חובת רישום מאגר או מינוי ממונה הגנת פרטיות תלוי בעובדות וספים שטרם אושרו. ראו <code>docs/legal/israel-compliance-audit.md</code>. <mark class=\"todo\">[מומלץ סקירה משפטית]</mark></p>\n<h2>18. אתרי צד שלישי</h2>\n<p>קישורים לאתרים אחרים אינם בשליטתנו.</p>\n<h2>19. שינויים</h2>\n<p>נפרסם שינויים כאן עם התאריך ונודיע לבעלי חשבון באפליקציה על שינויים מהותיים.</p>\n<h2>20. שפה</h2>\n<p>מסופקת גרסה עברית וגרסה אנגלית. <mark class=\"todo\">[מומלץ סקירה משפטית: איזו גרסה גוברת]</mark></p>\n<h2>21. יצירת קשר</h2>\n<p>מפעיל: Jonathan Zachevsky, ישראל. פרטיות: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>. כתובת דואר ציבורית: <mark class=\"todo\">[כתובת דואר ציבורית לא הוגדרה]</mark>.</p>"}, "terms": {"title": "תנאי שימוש", "file": "terms.html", "html": "<h1>תנאי שימוש (טיוטה)</h1>\n<blockquote class=\"draftNote\"><p><strong>טיוטה לבדיקה. אין זו ייעוץ משפטי והיא אינה סופית.</strong> הטקסט לא נבדק על ידי עורך דין. סעיפים המסומנים <code><mark class=\"todo\">[מומלץ סקירה משפטית]</mark></code> או <code><mark class=\"todo\">[נדרש מידע מהבעלים: ...]</mark></code> חייבים להיות מושלמים לפני ההשקה. אם יש הבדל בין הגרסה העברית לאנגלית, ראו את ההערה בסעיף 20. <mark class=\"todo\">[מומלץ סקירה משפטית: איזו גרסה גוברת]</mark></p></blockquote>\n<p>עדכון אחרון: <code>2026-10-01</code> (גרסת טיוטה <code>2026-10-01-draft</code>)</p>\n<h2>1. על <span class=\"bw\">Stick-It</span> ומי מפעיל אותה</h2>\n<p><span class=\"bw\">Stick-It</span> היא אפליקציית לוח שעם עם פתקים דביקים. היא מופעלת על ידי <strong>Jonathan Zachevsky</strong>, יחיד בישראל (\"אנחנו\"). לא הוקמה חברה. כתובת דואר ציבורית: <mark class=\"todo\">[כתובת דואר ציבורית לא הוגדרה]</mark>. פנייה לתמיכה: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>.</p>\n<h2>2. הסכמה לתנאים</h2>\n<p>בפתיחת חשבון, או בשימוש כאורח, אתם מסכימים לתנאים אלה ומאשרים שקראתם את <a href=\"privacy.html\">מדיניות הפרטיות</a>. אם אינכם מסכימים, אל תשתמשו ב-<span class=\"bw\">Stick-It</span>.</p>\n<h2>3. מי רשאי להשתמש, ואנשים צעירים</h2>\n<p><span class=\"bw\">Stick-It</span> שואלת \"בן/בת כמה אתם?\" לפני שמוצעת התחברות. אנחנו שומרים רק את התוצאה (בוגר, נער/ה או ילד/ה), לא את תאריך הלידה.</p>\n<ul><li><strong>גיל 18 ומעלה (בוגר/ת):</strong> מותר להשתמש, עם חשבון או בלעדיו.</li><li><strong>גיל 13 עד 17 (נער/ה):</strong> מותר להשתמש. החשבון מתחיל בהגדרות שמרניות: ללא דוא\"ל עדכוני מוצר, קישורי שיתוף ללא פרטי פרופיל כברירת מחדל וללא פרופיל ציבורי. <mark class=\"todo\">[מומלץ סקירה משפטית: כללי קטינים והסכמת אפוטרופוס בישראל]</mark></li><li><strong>מתחת לגיל 13 (ילד/ה):</strong> מותר להשתמש <strong>כאורח בלבד</strong>, כשהלוחות נשמרים במכשיר. חשבון ענן, שיתוף ותכונות ענן אחרות אינם זמינים עד שהורה או אפוטרופוס נתנו הסכמה מאומתת. <strong>מנגנון הסכמה מאומתת עדיין לא קיים</strong>, ולכן כרגע ילדים אינם יכולים לפתוח חשבון.</li></ul>\n<p>איננו משווקים לאף אחד מתחת לגיל 18. ראו את הדף <a href=\"young-people.html\">צעירים והורים</a>.</p>\n<h2>4. החשבון שלכם</h2>\n<ul><li>שמרו על ההתחברות שלכם (Google או GitHub). אתם אחראים לפעילות בחשבון.</li><li>מסרו פרטי פרופיל מדויקים ואל תתחזו לאחרים.</li><li>אפשר למחוק את החשבון בכל עת בהגדרות החשבון.</li></ul>\n<h2>5. התוכן שלכם והרישיון שאתם נותנים לנו</h2>\n<ul><li><strong>התוכן שלכם שייך לכם</strong> (פתקים, תמונות, הקלטות, סרטונים, לוחות, פרטי פרופיל). <span class=\"bw\">Stick-It</span> אינה טוענת לבעלות עליו.</li><li><strong>רישיון מוגבל.</strong> אתם מתירים לנו לאחסן, לגבות, להעתיק, להעביר ולהציג את התוכן <strong>רק ככל שנדרש להפעלת <span class=\"bw\">Stick-It</span> עבורכם</strong>. ההיתר פוקע עם מחיקת התוכן או החשבון, למעט עותקים בגיבויים וביומנים עד פקיעתם. <mark class=\"todo\">[מומלץ סקירה משפטית]</mark></li><li><strong>אתם אחראים לתוכן.</strong> אתם מצהירים שיש לכם זכות להעלות ולשתף אותו ושהוא אינו פוגע בזכויות אחרים ואינו מפר דין.</li></ul>\n<h2>6. שימוש מותר</h2>\n<p>אין להשתמש ב-<span class=\"bw\">Stick-It</span> כדי להעלות או לשתף תוכן בלתי חוקי, תוכן שמנצל או מסכן ילדים, מטריד, מאיים או מסית לאלימות, פוגע בפרטיות אחרים, מפר קניין רוחני או מכיל נוזקות; אין לסרוק, להעמיס או לעקוף מנגנוני גישה, מגבלות או את שלב הגיל; ואין לסייע לאחרים בכך. <mark class=\"todo\">[מומלץ סקירה משפטית: רשימה מלאה]</mark></p>\n<h2>7. שיתוף, קישורים ציבוריים ושיתוף פעולה</h2>\n<ul><li><strong>קישור שיתוף</strong> מציג את מה ששיתפתם לכל מי שמחזיק בקישור, ללא חשבון. הקישור פעיל עד שתכבו אותו. קישור <strong>צילום מצב</strong> מציג עותק קפוא; קישור <strong>לוח חי</strong> מציג את הלוח כולו, לקריאה בלבד.</li><li>מה שהקישור מציג עליכם (שם, תמונה, אודות) הוא מה שבחרתם בהגדרות החשבון בעת יצירת הקישור.</li><li><strong>משתפי פעולה</strong> שתזמינו יכולים לראות, ובתפקיד עורך גם לשנות, את הלוח.</li><li>מי שקיבל קישור יכול לשמור עותקים. איננו יכולים להחזיר מה שאחרים שמרו.</li></ul>\n<h2>8. הסרת תוכן והשעיה</h2>\n<p>אנו רשאים להסיר או לנטרל תוכן או קישורים, או להשעות או לסיים חשבונות, אם יש לנו יסוד סביר להניח שהתנאים או הדין הופרו, כדי להשיב לתלונה או בקשה משפטית תקפה, או כדי להגן על אנשים או על השירות. ככל שניתן נסביר מדוע. <mark class=\"todo\">[מומלץ סקירה משפטית: הליך הודעה וערעור]</mark></p>\n<h2>9. תלונות על זכויות יוצרים</h2>\n<p>אם אתם סבורים שתוכן ב-<span class=\"bw\">Stick-It</span> מפר זכויות יוצרים שלכם, ראו את <a href=\"copyright.html\">דף זכויות היוצרים</a>. <span class=\"bw\">Stick-It</span> <strong>לא</strong> רשמה סוכן ייעודי לפי ה-DMCA האמריקאי, ובדין הישראלי אין מנגנון \"נמל מבטחים\" זהה, ולכן הדף מתאר הליך תום-לב משלנו. <mark class=\"todo\">[מומלץ סקירה משפטית]</mark></p>\n<h2>10. פרטיות</h2>\n<p>הטיפול במידע אישי מתואר ב<a href=\"privacy.html\">מדיניות הפרטיות</a>.</p>\n<h2>11. זמינות וגיבויים</h2>\n<p><span class=\"bw\">Stick-It</span> ניתנת בעודה בפיתוח. היא עלולה להשתנות, להיפסק או לכלול תקלות. <strong>איננו מבטיחים שדבר לא יאבד.</strong> שמרו עותק משלכם של מה שחשוב: השתמשו בייצוא בהגדרות. לוחות אורח נשמרים רק בדפדפן ועלולים ללכת לאיבוד בניקוי נתוני הדפדפן.</p>\n<h2>12. מסלולים ותשלומים</h2>\n<p>כיום ל-<span class=\"bw\">Stick-It</span> <strong>אין מסלול בתשלום והיא אינה גובה תשלום.</strong> אם יתווספו מסלולים, המחיר, תקופת החיוב, חידוש אוטומטי, דרך הביטול וכללי החזר יוצגו ליד כפתור הרכישה לפני התשלום, והתנאים יעודכנו.</p>\n<h2>13. סיום השימוש</h2>\n<p>אפשר להפסיק להשתמש ולמחוק את החשבון בכל עת. אנו רשאים לשנות או להפסיק את השירות, ובמקרה כזה ננסה לתת הודעה ואפשרות לייצא.</p>\n<h2>14. הסתייגות מאחריות</h2>\n<p><span class=\"bw\">Stick-It</span> ניתנת \"כפי שהיא\" ו\"כפי שהיא זמינה\" ככל שהדין מתיר. זכויות שאי אפשר לוותר עליהן בחוזה, ובכלל זה זכויות צרכן, אינן נפגעות. <mark class=\"todo\">[מומלץ סקירה משפטית]</mark></p>\n<h2>15. הגבלת אחריות</h2>\n<p>ככל שהדין מתיר, איננו אחראים לנזק עקיף או תוצאתי או לאובדן נתונים שלא גיביתם. שום דבר בתנאים אינו מגביל אחריות שאי אפשר להגבילה בדין, לרבות הגנות צרכן קוגנטיות. <mark class=\"todo\">[מומלץ סקירה משפטית]</mark></p>\n<h2>16. שיפוי</h2>\n<p>אם תוכן שלכם או הפרת התנאים גורמים לתביעת צד שלישי נגדנו, תסייעו לנו להתמודד איתה ככל שהדין מתיר. <mark class=\"todo\">[מומלץ סקירה משפטית: האם לכלול סעיף זה כלפי צרכנים]</mark></p>\n<h2>17. דין וסמכות שיפוט (מוצע)</h2>\n<p><strong>מוצע:</strong> דיני <strong>מדינת ישראל</strong>, וסמכות לבתי המשפט המוסמכים ב<strong>מחוז תל אביב-יפו</strong>, <strong>בכפוף להגנות צרכן קוגנטיות המקנות לכם זכויות אחרות</strong>. <mark class=\"todo\">[מומלץ סקירה משפטית: זו הצעה של הבעלים ולא נבדקה על ידי עורך דין]</mark></p>\n<h2>18. שינויים בתנאים</h2>\n<p>אנו רשאים לעדכן את התנאים. נפרסם את הגרסה החדשה ותאריכה ונודיע לבעלי חשבון באפליקציה על שינויים מהותיים. המשך שימוש לאחר שינוי פירושו הסכמה. <mark class=\"todo\">[מומלץ סקירה משפטית]</mark></p>\n<h2>19. סיום עקב הפרה</h2>\n<p>אנו רשאים להשעות או לסיים את הגישה שלכם אם הפרתם את התנאים הפרה חמורה או חוזרת. סעיפים שמטבעם נמשכים לאחר הסיום ימשיכו לחול.</p>\n<h2>20. כללי ושפה</h2>\n<p>אם חלק מהתנאים אינו ניתן לאכיפה, השאר ממשיך לחול. אי אכיפה מיידית אינה ויתור. אין להעביר את החשבון לאחר. אם יש הבדל בין הגרסה העברית לאנגלית, <mark class=\"todo\">[מומלץ סקירה משפטית: איזו גרסה גוברת]</mark>.</p>\n<h2>21. יצירת קשר</h2>\n<p>מפעיל: Jonathan Zachevsky, ישראל. תמיכה: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>. פרטיות: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>. זכויות יוצרים: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>. כתובת דואר ציבורית: <mark class=\"todo\">[כתובת דואר ציבורית לא הוגדרה]</mark>.</p>"}, "copyright": {"title": "זכויות יוצרים", "file": "copyright.html", "html": "<h1>זכויות יוצרים (טיוטה)</h1>\n<blockquote class=\"draftNote\"><p><strong>דף לפיתוח בלבד. אינו סופי.</strong> <span class=\"bw\">Stick-It</span> <strong>לא</strong> רשמה סוכן ייעודי לפי ה-DMCA האמריקאי. אין בדף זה כדי להוות רישום כזה. טופס התלונה בדף האנגלי נשאר מוסתר עד שהבעלים משלים את הצעדים. בדיני ישראל אין מנגנון \"נמל מבטחים\" זהה ל-DMCA, ולכן הדף מתאר הליך תום-לב משלנו. <mark class=\"todo\">[מומלץ סקירה משפטית]</mark></p></blockquote>\n<h2>דיווח על הפרת זכויות יוצרים</h2>\n<p><span class=\"bw\">Stick-It</span> מאפשרת לאנשים ליצור, להדביק, להעלות ולשתף תוכן. המשתמשים אחראים לוודא שיש להם הזכויות או ההיתר הדרושים למה שהם מוסיפים. <span class=\"bw\">Stick-It</span> אינה בודקת באופן יזום כל לוח פרטי לגבי בעלות בזכויות יוצרים. אם מתקבלת תלונה תקפה על הפרת זכויות יוצרים, <span class=\"bw\">Stick-It</span> רשאית לחקור ולהגביל או להסיר את החומר שדווח כשמתאים. דף זה אינו מגביל אחריות שיש ל-<span class=\"bw\">Stick-It</span> על פי הדין. אם אתם בעלי זכויות יוצרים (או מוסמכים לפעול בשמם) וסבורים שתוכן ב-<span class=\"bw\">Stick-It</span> מפר את זכויותיכם, שלחו הודעה לכתובת הקשר הכללית לזכויות יוצרים: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>. כתובת זו היא איש קשר כללי בלבד, <strong>אינה</strong> סוכן DMCA רשום, ואין לתארה ככזו עד שהרישום יושלם.</p>\n<h2>מה ההודעה צריכה לכלול</h2>\n<p>(1) חתימה פיזית או אלקטרונית; (2) זיהוי היצירה שלדעתכם הופרה; (3) זיהוי החומר ו<strong>איפה הוא</strong> (בקישור השיתוף או בכתובת הדף); (4) פרטי הקשר שלכם; (5) הצהרה שיש לכם אמונה בתום לב שהשימוש אינו מורשה על ידי בעל הזכויות, שלוחו או הדין; (6) הצהרה שהפרטים מדויקים ושאתם בעלי הזכויות או מוסמכים לפעול בשמם.</p>\n<p>אנא היו מדויקים. הצגה מכוונת של חומר כמפר כשאינו כזה עלולה לגרור השלכות משפטיות.</p>\n<h2>מה קורה אחר כך</h2>\n<p>אנו בוחנים הודעות. אם הודעה שלמה ונראית תקפה, ייתכן שנסיר או ננטרל את החומר ונודיע למי שהעלה או שיתף. <mark class=\"todo\">[נדרש מידע מהבעלים / מומלץ סקירה משפטית: ההליך והמועדים]</mark></p>\n<h2>הודעת נגד</h2>\n<p>אם התוכן שלכם הוסר ואתם סבורים שזו טעות או שיש לכם זכות להשתמש בו, אפשר לשלוח הודעת נגד לאותה כתובת. <mark class=\"todo\">[מומלץ סקירה משפטית]</mark></p>\n<h2>מפרים חוזרים</h2>\n<p><mark class=\"todo\">[מומלץ סקירה משפטית: מדיניות מפרים חוזרים]</mark></p>\n<h2>תלונות אחרות</h2>\n<p>לבקשות פרטיות ראו את <a href=\"privacy.html\">מדיניות הפרטיות</a>. להתעללות אחרת השתמשו בקישור <strong>דיווח</strong> בכל דף משותף.</p>"}, "young": {"title": "צעירים והורים", "file": "young-people.html", "html": "<h1>צעירים והורים (טיוטה)</h1>\n<blockquote class=\"draftNote\"><p><strong>טיוטה לבדיקה. אין זו ייעוץ משפטי והיא אינה סופית.</strong> <mark class=\"todo\">[מומלץ סקירה משפטית]</mark></p></blockquote>\n<p><span class=\"bw\">Stick-It</span> שואלת \"בן/בת כמה אתם?\" לפני שמוצעת התחברות. אנו שומרים רק את התוצאה, לעולם לא את תאריך הלידה.</p>\n<h2>מה כל קבוצת גיל יכולה</h2>\n<div class=\"tableWrap\"><table><thead><tr><th scope=\"col\">גיל</th><th scope=\"col\">מה קורה</th></tr></thead><tbody><tr><td><strong>18 ומעלה</strong></td><td>שימוש מלא, עם חשבון או בלעדיו.</td></tr><tr><td><strong>13 עד 17</strong></td><td>חשבון מותר עם הגדרות שמרניות: ללא דוא\"ל עדכוני מוצר, קישורי שיתוף ללא פרטי פרופיל כברירת מחדל, ללא פרופיל ציבורי.</td></tr><tr><td><strong>מתחת ל-13</strong></td><td>שימוש כאורח בלבד. הלוחות נשארים בדפדפן במכשיר. חשבון ענן, שיתוף ותכונות ענן דורשים הסכמה מאומתת של הורה או אפוטרופוס.</td></tr></tbody></table></div>\n<h2>הסכמת הורים: המצב האמיתי</h2>\n<p>הליך מאומת להסכמת הורים <strong>עדיין לא קיים</strong>. עד שיהיה, ילדים מתחת ל-13 יכולים להשתמש רק כאורחים. לא נעמיד פנים שלחיצה או כתובת דוא\"ל הן הסכמה מאומתת.</p>\n<p>אם נוצר בכל זאת חשבון ענן לילד (למשל בעקיפת שלב הגיל), החשבון <strong>מוגבל ונשאר בהמתנה</strong>: תכונות ענן חסומות, איננו מוחקים אותו אוטומטית, והורה או אפוטרופוס יכולים לבקש מחיקה.</p>\n<h2>מה איננו עושים לצעירים</h2>\n<ul><li>אין דוא\"ל שיווקי לאף אחד מתחת לגיל 18.</li><li>אין פרופילים ציבוריים כברירת מחדל.</li><li>אין פרסום ואין מעקב. (כיום אין אנליטיקת מוצר; אם זה ישתנה, מדיניות הפרטיות תעודכן קודם, והאנליטיקה לעולם לא תקרא פתקים, תגובות, חיפושים או מדיה פרטית.) <mark class=\"todo\">[מומלץ סקירה משפטית]</mark></li><li>איננו אוספים תאריך לידה.</li></ul>\n<h2>להורים ולאפוטרופוסים</h2>\n<p>כדי לשאול איזה מידע יש לנו על ילד או לבקש מחיקת חשבון, כתבו אל <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a> וציינו איזה חשבון התחברות. ייתכן שנצטרך לוודא שאתם ההורה או האפוטרופוס.</p>\n<p>ראו גם את <a href=\"privacy.html\">מדיניות הפרטיות</a> ואת <a href=\"terms.html\">התנאים</a>.</p>"}, "storage": {"title": "הודעת אחסון", "file": "storage.html", "html": "<h1>הודעת אחסון (טיוטה)</h1>\n<blockquote class=\"draftNote\"><p><strong>טיוטה לבדיקה.</strong> <mark class=\"todo\">[מומלץ סקירה משפטית]</mark></p></blockquote>\n<p>כיום <span class=\"bw\">Stick-It</span> אינה מציבה עוגיות משלה. במקום זאת היא משתמשת באחסון הדפדפן, כגון אחסון מקומי ו-IndexedDB, ללוחות אורח, העדפות, עותק מקומי של לוחות ומידע הקשור להפעלה. טכנולוגיות אלה משרתות מטרות שמירה דומות אך שונות טכנית מעוגיות. הן בשימוש משום שהאפליקציה זקוקה להן כדי לעבוד:</p>\n<div class=\"tableWrap\"><table><thead><tr><th scope=\"col\">מה</th><th scope=\"col\">למה</th></tr></thead><tbody><tr><td>לוחות ופתקי אורח</td><td>שהעבודה תמתין לכם בפעם הבאה</td></tr><tr><td>הגדרות (ערכת נושא, גופנים, העדפות)</td><td>לזכור את בחירותיכם</td></tr><tr><td>גזירות שיצרתם כאורחים (תמונות שקופות קטנות ב-IndexedDB של הדפדפן) והערה שראיתם את טיפי הגזירה</td><td>כדי שהגזירות יחכו לכם בפעם הבאה</td></tr><tr><td>תוצאת שלב הגיל (בוגר או נער/ה, עם חותמת זמן, לעולם לא תאריך לידה). עותק קצר-טווח משמש כשעה בזמן ההתחברות; עותק ארוך-טווח נחשב אמין עד 90 יום בדפדפן שבו התחברתם (אחריהם מתעלמים ממנו; הרשומה הישנה נשארת עד שתוחלף או שתנקו את נתוני הדפדפן)</td><td>כדי לא לשאול שוב בכל התחברות</td></tr><tr><td>הזמנה ממתינה ללוח, נשמרת באחסון ההפעלה של הלשונית בלבד עד שתסיימו להתחבר</td><td>כדי שההזמנה תשרוד את שלב ההתחברות</td></tr><tr><td>בעת התחברות: ההפעלה ועותק מקומי של הלוחות</td><td>להתחבר ולהציג לוחות במהירות או בלי רשת</td></tr></tbody></table></div>\n<p>כיום <span class=\"bw\">Stick-It</span> אינה משתמשת בכלי פרסום או הקלטת מסך. ייתכן שתוכנס אנליטיקת מוצר כדי להבין איך משתמשים בשירות, כגון ספירת חשבונות, לוחות, סוגי עצמים, שימוש בתכונות, שגיאות וביצועים. אנליטיקה לא תאסוף תוכן כגון טקסט פתקים, טקסט תגובות, שאילתות חיפוש, טקסט של לוחות פרטיים או תמונות, סרטונים והקלטות פרטיים. אם האנליטיקה תופעל, הודעה זו ומדיניות הפרטיות יעודכנו יחד. ספקי סרטונים מוטמעים, עיבוד תשלומים או אנליטיקה עשויים להשתמש בעתיד בעוגיות או בטכנולוגיות דומות, וההודעה תעודכן אם זה ישתנה.</p>\n<p>האחסון שברשימה נחוץ לחלוטין למתן מה שביקשתם. ניקוי נתוני הדפדפן מסיר אותו, והתנתקות מסירה את העותק המחובר. לוחות אורח אינם נשלחים אלינו; ניקוי נתוני הדפדפן מוחק אותם לצמיתות אלא אם ייצאתם אותם.</p>\n<p>ראו את <a href=\"privacy.html\">מדיניות הפרטיות</a>.</p>"}, "accessibility": {"title": "הצהרת נגישות", "file": "accessibility.html", "html": "<h1>הצהרת נגישות (טיוטה)</h1>\n<blockquote class=\"draftNote\"><p><strong>טיוטה לבדיקה. אין זו תעודת התאמה.</strong> <mark class=\"todo\">[מומלץ סקירה משפטית]</mark></p></blockquote>\n<p>עדכון אחרון: <code>2026-10-01</code></p>\n<p><span class=\"bw\">Stick-It</span> הוא פרויקט אישי של Jonathan Zachevsky, ישראל. <span class=\"bw\">Stick-It</span> שואפת לעמוד ב-<strong>WCAG 2.2 ברמה AA</strong> כיעד הנגישות של פיתוח המוצר. במקום שבו חלות על <span class=\"bw\">Stick-It</span> דרישות נגישות ישראליות, אנו שואפים לעמוד גם בדרישות הרלוונטיות של התקן הישראלי ת\"י 5568 ושל תקנות שוויון זכויות לאנשים עם מוגבלות. אלה מקורות נפרדים: ת\"י 5568 אינו פשוט זהה ל-WCAG 2.2. <strong>לא נערכה ביקורת על ידי מומחה נגישות מוסמך ואיננו טוענים לאישור או להתאמה מאומתת.</strong></p>\n<h2>מה עשינו</h2>\n<ul><li>מקלדת: חלונות שמנהלים מיקוד ומחזירים אותו, מקש <code>N</code> יוצר פתק, מסגרות מיקוד גלויות.</li><li>קישור דילוג, בקרות מתויגות, תמיכה בהפחתת תנועה.</li><li>ניגודיות צבעים נבדקה לטקסט ולכפתורים הראשיים בערכת נושא בהירה וכהה.</li><li>גופנים מתארחים עצמית כולל עברית וערבית; דפים בעברית הם מימין לשמאל.</li></ul>\n<h2>מגבלות ידועות</h2>\n<ul><li>פתקים ממוקמים בגרירה. קיימת הזזה במקלדת לפתק נבחר, אך בחירה וסידור פתקים בלי עכבר מוגבלים.</li><li>בקרות הקלטה וסרטון לא נבדקו עם טכנולוגיה מסייעת.</li><li>לא כל הודעת מצב מוכרזת לקורא מסך.</li><li>לא נבדק עם NVDA, JAWS או VoiceOver על ידי אנשים עם מוגבלות, ולא מעבר להגדלה של 200%.</li><li>עדיין לא נבדק בטלפונים וטאבלטים פיזיים עם טכנולוגיה מסייעת.</li><li>דפדוף בערימות, סרטון מוטמע וקורא המסמכים המשפטיים שבאפליקציה חדשים ועברו רק בדיקות מפתחים, לא בדיקה עם טכנולוגיה מסייעת.</li></ul>\n<h2>יצירת קשר</h2>\n<p>אם אינכם מצליחים להשתמש בחלק מ-<span class=\"bw\">Stick-It</span>, כתבו מה ניסיתם, מה עצר אתכם, באיזה דפדפן אתם משתמשים ואם ידוע לכם, באיזו טכנולוגיה מסייעת: <a href=\"mailto:support.stickit@gmail.com\">support.stickit@gmail.com</a>. ננסה להשיב ולהציע דרך חלופית. רכז הנגישות ושאר הפרטים הנדרשים בהצהרה הם פעולות פתוחות של הבעלים: ראו <code>docs/legal/israel-accessibility.md</code>.</p>"}}}}; })(typeof window !== 'undefined' ? window : globalThis);
